record.field:
if record.x_document_type == 'file':
    url = f"/web/content/{record._name}/{record.id}/x_file_content/{record.x_name}?download=1&mimetype={record.x_mimetype or 0}"
    action = {
        'type': 'ir.actions.act_url',
        'url': url,
        'target': 'download',
    }

folder = env.ref("x_document.document_folder_inbox", raise_if_not_found=False)
if folder:
    if folder.id in records.ids:
        raise UserError("Inbox Folder can not be deleted !")

new_records = env["x_document.document"]
for document in records.filtered(lambda d: d.x_document_type == 'inbox'):
    if document.message_ids:
        message = document.message_ids[0]
        for index, attachment in enumerate(message.attachment_ids):
            if index == 0:
                target_document = document
            else:
                target_document = document.copy()

            attachment.copy({
                "res_field": "x_file_content",
                "name": "x_file_content",
                "res_id": target_document.id,
            })
            new_records |= target_document

new_records.write({"x_document_type": "file"}) # change type to retrigger mimetype computation
